ee:message.ee:set-payload:
%dw 2.0
output application/json
var offset = vars.OffSet as Number default 0
var docs = payload default []
---
if (isEmpty(docs) or (sizeOf(docs) <= offset))
{
  "status": 404,
  "code": "NOT_FOUND",
  "message": {
    "message": ""
  },
  "messageServer": "Data not found",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.exception.NotFoundExcecption"
    }
  ]
}
else
docs[offset to -1]
